import {isKnowledge,relevant,text} from './knowledge.js';
const $=s=>document.querySelector(s);
const topics=['全部','AI 与科技','思维与学习','科学与数学','社会与世界','人文与艺术','生活与成长'];
const storageRead=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const stored=storageRead('ub-bili-library',[]);const library=new Map((Array.isArray(stored)?stored:[]).filter(x=>x&&/^BV[0-9A-Za-z]{10}$/.test(x.id)).map(x=>[x.id,x]));
const saved=new Set(storageRead('ub-saved',[]));let history=storageRead('ub-history',[]),questions=storageRead('ub-questions',[]);
if(!Array.isArray(history))history=[];if(!Array.isArray(questions))questions=[];
let indexed=[],results=[],view='explore',topic='全部',batch=0,deadline=null,active=null,requestId=0,searchController=null,hasMore=false,livePage=1,loading=false;
const liveAvailable=!location.hostname.endsWith('github.io');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('ub-saved',JSON.stringify([...saved]));localStorage.setItem('ub-history',JSON.stringify(history));localStorage.setItem('ub-questions',JSON.stringify(questions));const keep=new Set([...saved,...history,...indexed.map(x=>x.id),...results.map(x=>x.id)]);localStorage.setItem('ub-bili-library',JSON.stringify([...library.values()].filter(x=>keep.has(x.id)).slice(-300)))}catch{toast('当前浏览器无法保存记录')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function duration(value){const total=Number(value)||0;return total>=3600?`${Math.floor(total/3600)}:${String(Math.floor(total/60)%60).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`:`${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`}
function setState(message){$('#searchStatus').textContent=message}
$('.topics').innerHTML=topics.map(t=>`<button class="topic${t===topic?' active':''}" aria-pressed="${t===topic}" data-topic="${t}">${t}</button>`).join('');
$('#searchMode').innerHTML='<option value="index">目录</option>'+(liveAvailable?'<option value="live">实时</option>':'');
function render(){const query=$('#search').value.trim();let pool=view==='saved'?[...saved].map(id=>library.get(id)).filter(Boolean):view==='history'?history.map(id=>library.get(id)).filter(Boolean):results;
 const unfiltered=pool.length;pool=pool.filter(x=>(!$('#knowledgeOnly').checked||isKnowledge(x))&&(topic==='全部'||x.topic===topic)&&($('#searchMode').value==='live'&&view==='explore'?true:relevant(x,query)));
 const list=pool.slice(batch*6,batch*6+6);
 $('#cards').innerHTML=list.map(c=>`<article class="card"><div class="art cover-art"><button class="content-open" data-open="${escape(c.id)}" aria-label="站内播放：${escape(c.title)}"><img src="${escape(c.cover)}" alt="${escape(c.title)}" loading="lazy" referrerpolicy="no-referrer"><span class="play-icon" aria-hidden="true">▷</span></button><span class="format">${duration(c.duration)}</span><button class="save" data-save="${escape(c.id)}" aria-label="${saved.has(c.id)?'取消收藏':'收藏'}：${escape(c.title)}" aria-pressed="${saved.has(c.id)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h12v17l-6-4-6 4z"/></svg></button></div><button class="title-open" data-open="${escape(c.id)}"><h3>${escape(c.title)}</h3></button><div class="card-meta"><span class="card-source">B站 · ${escape(c.author)}</span><a class="external" href="https://www.bilibili.com/video/${escape(c.bvid)}/" target="_blank" rel="noopener noreferrer" aria-label="查看原视频：${escape(c.title)}">↗</a></div></article>`).join('');
 $('#cards').querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;const fallback=document.createElement('span');fallback.className='cover-unavailable';fallback.textContent='封面暂不可用';img.parentElement.append(fallback)},{once:true}));
 $('#empty').hidden=list.length>0||loading;$('#cards').setAttribute('aria-busy',String(loading));$('#batchEnd').hidden=loading||!(pool.length>(batch+1)*6||(hasMore&&view==='explore'));
 $('#resultSummary').textContent=`${pool.length} 项结果；筛除 ${unfiltered-pool.length} 项；第 ${batch+1} 组`;
 $('#savedCount').textContent=[...saved].filter(id=>library.has(id)).length;$('#sectionTitle').textContent=view==='saved'?'收藏':view==='history'?'足迹':'发现';
 if(view==='history'&&questions.length){const section=document.createElement('section');section.className='question-list';const title=document.createElement('h3');title.textContent='问题';section.append(title);questions.slice(-5).reverse().forEach(q=>{const p=document.createElement('p');p.textContent=q.text;section.append(p)});$('#cards').append(section);$('#empty').hidden=true}
 $('.topics').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.topic===topic);b.setAttribute('aria-pressed',String(b.dataset.topic===topic))});
 $('#searchForm button[type=submit]').disabled=loading;
}
async function loadIndex(){loading=true;render();setState('加载 B站目录…');try{const response=await fetch('./data/bilibili.json');if(!response.ok)throw Error('目录加载失败');const data=await response.json();indexed=data.items.filter(x=>/^BV[0-9A-Za-z]{10}$/.test(x.bvid)&&/^https:\/\/i[0-9]\.hdslb\.com\//.test(x.cover));indexed.forEach(x=>library.set(x.id,x));results=indexed;setState(`B站目录 · ${indexed.length} 项`);$('#indexUpdated').textContent=new Date(data.updatedAt).toLocaleString('zh-CN');persist()}catch{setState('目录暂不可用，请刷新重试')}finally{loading=false;render()}}
async function searchLive(next=false){const query=$('#search').value.trim();if(!query){results=indexed;setState(`B站目录 · ${indexed.length} 项`);batch=0;render();return}searchController?.abort();searchController=new AbortController();const id=++requestId;loading=true;render();setState('搜索中…');const timeout=setTimeout(()=>searchController?.abort(),15000);try{const page=next?livePage+1:1;const response=await fetch(`./api/search?q=${encodeURIComponent(query)}&page=${page}`,{signal:searchController.signal});const data=await response.json();if(id!==requestId)return;if(!response.ok)throw Error(data.error||'实时搜索不可用');const items=data.items.filter(x=>/^BV[0-9A-Za-z]{10}$/.test(x.id)&&/^https:\/\/i[0-9]\.hdslb\.com\//.test(x.cover));items.forEach(x=>library.set(x.id,x));results=next?[...new Map([...results,...items].map(x=>[x.id,x])).values()]:items;livePage=page;hasMore=data.hasMore;batch=next?batch+1:0;setState(`B站实时 · ${results.length} 项 · 已筛除 ${data.filtered||0} 项`);persist()}catch(e){if(id!==requestId)return;results=indexed;batch=0;hasMore=false;$('#searchMode').value='index';setState('实时搜索不可用，已切换目录');toast(e.name==='AbortError'?'B站搜索超时，当前显示目录结果':`${e.message}；当前显示目录结果`)}finally{clearTimeout(timeout);if(id===requestId){loading=false;render()}}}
function openContent(id){const item=library.get(id);if(!item)return;active=item;history=[id,...history.filter(x=>x!==id)].slice(0,100);persist();$('#viewerTitle').textContent=item.title;$('#viewerAuthor').textContent=`B站 · ${item.author}`;$('#originalLink').href=`https://www.bilibili.com/video/${item.bvid}/`;$('#videoDescription').textContent=item.desc||'原视频暂无简介。';$('#parts').replaceChildren();(item.pages?.length?item.pages:[{page:1,part:'第 1 集'}]).forEach(p=>{const option=document.createElement('option');option.value=p.page;option.textContent=`${p.page}. ${p.part}`;$('#parts').append(option)});$('#parts').hidden=(item.pages?.length||1)<2;$('#viewer').showModal();setViewerTab('watch');loadPlayer(1);}
function loadPlayer(page){if(!active)return;const player=document.createElement('iframe');const url=new URL('https://player.bilibili.com/player.html');url.search=new URLSearchParams({bvid:active.bvid,p:String(page),autoplay:'0',danmaku:'0',poster:'1'});player.src=url.href;player.title=active.title;player.allow='fullscreen; picture-in-picture; encrypted-media';player.allowFullscreen=true;player.referrerPolicy='strict-origin-when-cross-origin';$('#playerFrame').replaceChildren(player);$('#playerHint').hidden=false;player.addEventListener('load',()=>{$('#playerHint').textContent='播放由 B站提供；如受限，可查看原视频。'},{once:true});}
function setViewerTab(tab){const reading=tab==='read';$('#watchPane').hidden=reading;$('#readPane').hidden=!reading;$('#watchTab').setAttribute('aria-selected',String(!reading));$('#readTab').setAttribute('aria-selected',String(reading));}
$('#viewer').addEventListener('close',()=>{$('#playerFrame').replaceChildren();active=null});$('#viewerClose').onclick=()=>$('#viewer').close();$('#watchTab').onclick=()=>setViewerTab('watch');$('#readTab').onclick=()=>setViewerTab('read');$('#parts').onchange=()=>loadPlayer(Number($('#parts').value));
$('#searchForm').addEventListener('submit',e=>{e.preventDefault();batch=0;if($('#searchMode').value==='live'&&view==='explore')searchLive();else{results=indexed;hasMore=false;render()}});
$('#search').addEventListener('input',()=>{searchController?.abort();requestId++;loading=false;hasMore=false;batch=0;if($('#searchMode').value==='index'){results=indexed}else{results=[];setState('B站实时 · 输入后搜索')}render()});
$('#searchMode').onchange=()=>{searchController?.abort();requestId++;loading=false;batch=0;hasMore=false;results=indexed;setState($('#searchMode').value==='live'?'B站实时 · 输入后搜索':`B站目录 · ${indexed.length} 项`);render()};$('#knowledgeOnly').onchange=()=>{batch=0;render()};
function switchView(next){searchController?.abort();requestId++;loading=false;view=next;topic='全部';batch=0;hasMore=false;results=indexed;$('#search').value='';$('#searchMode').value='index';setState(next==='explore'?`B站目录 · ${indexed.length} 项`:'');document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);if(n.dataset.view===view)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});render()}
$('#reset').onclick=()=>switchView('explore');$('#more').onclick=()=>{const pool=results.filter(x=>(!$('#knowledgeOnly').checked||isKnowledge(x))&&(topic==='全部'||x.topic===topic)&&($('#searchMode').value==='live'||relevant(x,$('#search').value)));if(pool.length>(batch+1)*6){batch++;render()}else if(hasMore)searchLive(true);$('.library').scrollIntoView({block:'start'})};
 document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);persist();render();return}const open=e.target.closest('[data-open]');if(open){e.preventDefault();openContent(open.dataset.open);return}const t=e.target.closest('[data-topic]');if(t){topic=t.dataset.topic;batch=0;render()}const nav=e.target.closest('[data-view]');if(nav)switchView(nav.dataset.view)});
function updateTimer(){const b=$('#focus');b.classList.toggle('running',deadline!==null);if(deadline){const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));b.querySelector('span').textContent=duration(remaining);if(!remaining){deadline=null;if($('#viewer').open)$('#viewer').close();$('#reflection').showModal();updateTimer()}}else b.querySelector('span').textContent='20:00';b.setAttribute('aria-label',deadline?'结束本次探索':'开始 20 分钟探索')}
$('#focus').onclick=()=>{if(deadline){deadline=null;$('#reflection').showModal()}else{deadline=Date.now()+1200000;toast('计时开始 · 关闭页面后不再提醒')}updateTimer()};setInterval(updateTimer,1000);
$('#saveQuestion').onclick=e=>{const value=$('#question').value.trim();if(!value){e.preventDefault();$('#question').focus();return}questions.push({text:value,date:new Date().toISOString()});persist();$('#question').value='';toast('已保存到足迹');if(view==='history')render()};$('#about').onclick=()=>$('#info').showModal();
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});loadIndex();
